CREATE TABLE event_outbox (id VARCHAR(64) PRIMARY KEY, event_id VARCHAR(64) NOT NULL UNIQUE, topic VARCHAR(96) NOT NULL, status VARCHAR(16) NOT NULL, attempt_count INTEGER NOT NULL DEFAULT 0, available_at VARCHAR(40) NOT NULL, delivered_at VARCHAR(40) NULL, created_at VARCHAR(40) NOT NULL, CONSTRAINT fk_event_outbox_event FOREIGN KEY (event_id) REFERENCES space_events(id) ON DELETE CASCADE, CONSTRAINT chk_event_outbox_status CHECK (status IN ('pending','delivered','failed')), CONSTRAINT chk_event_outbox_attempts CHECK (attempt_count >= 0));
-- statement-break
CREATE INDEX idx_event_outbox_pending ON event_outbox(status, available_at);
